svg.script:
(function() {
  const ids = ['r1_1','r1_2','r1_3','r1_4','r1_5','r1_6','r1_7','r2_1','r2_2','r2_3','r2_4','r2_5','r2_6','r2_7','r3_1','r4_1','r4_2','r4_3','r4_4','r4_5','r4_6','r5_1','r5_2','r5_3','r5_4','r5_5','r5_6','r5_7'];
  const hand = document.getElementById('handPencil');

  function sleep(ms) {
    return new Promise(r => setTimeout(r, ms));
  }

  function tangent(path, len, dist) {
    const p = path.getPointAtLength(dist);
    const p2 = path.getPointAtLength(Math.min(len, dist + 1.5));
    return {
      x:p.x,
      y:p.y,
      a:Math.atan2(p2.y-p.y, p2.x-p.x) * 180 / Math.PI
    };
  }

  async function drawPath(id) {
    const guide = document.getElementById(id);
    const trace = document.getElementById('trace_' + id);
    const len = guide.getTotalLength();
    const start = tangent(guide, len, 0);

    // انتقال سريع إلى بداية السهم، بدون رسم أثناء الانتقال.
    hand.style.transition = 'transform 300ms ease-in-out';
    hand.setAttribute('transform', `translate(${start.x} ${start.y}) rotate(${start.a})`);
    await sleep(330);

    trace.style.transition = 'none';
    trace.style.strokeDashoffset = '1';
    trace.style.opacity = '.96';

    // سرعة ثابتة تقريبًا حتى تكون حركة القلم تعليمية وواضحة.
    const duration = Math.max(520, Math.min(1700, len * 4.4));
    const tStart = performance.now();
    hand.style.transition = 'none';

    await new Promise(resolve => {
      function frame(now) {
        const raw = Math.min(1, (now - tStart) / duration);
        const t = raw < .5 ? 2*raw*raw : 1 - Math.pow(-2*raw+2, 2)/2;
        const dist = len * t;
        const p = tangent(guide, len, dist);

        // رأس القلم يثبت على مركز المسار نفسه.
        hand.setAttribute('transform', `translate(${p.x} ${p.y}) rotate(${p.a})`);
        trace.style.strokeDashoffset = String(1 - t);

        if (raw < 1) requestAnimationFrame(frame);
        else resolve();
      }
      requestAnimationFrame(frame);
    });

    await sleep(110);
  }

  async function loop() {
    while (true) {
      // في بداية كل دورة تختفي الخطوط المرسومة، ثم يعيد القلم التدريب من أول سهم.
      ids.forEach(id => {
        const tr = document.getElementById('trace_' + id);
        tr.style.opacity = '0';
        tr.style.strokeDashoffset = '1';
      });
      await sleep(450);

      for (const id of ids) {
        await drawPath(id);
      }

      // إبقاء جميع الخطوط المتصلة ظاهرة قليلًا قبل إعادة التدريب.
      await sleep(1200);
    }
  }

  setTimeout(loop, 650);
})();
